package com.syrmos.core.common

/**
 * Syrmos 3.0.2: real station closures with a time window.
 *
 * One pure, offline rule shared by the server projector, Kotlin (this file),
 * Swift `StationClosures.swift` and web, validated case for case against
 * `fixtures/closures/effect.json` (generated by `scripts/generate-302-fixtures.py`).
 * The client evaluates the window itself, so a closure scheduled for 08:00 flips
 * at 08:00 even with no network; the server `status` field is informational only,
 * except that `draft` and `cancelled` closures never apply.
 */

/** A text the server sends in up to four languages. Any key may be missing. */
data class LocalizedText(
    val en: String? = null,
    val el: String? = null,
    val sq: String? = null,
    val it: String? = null,
) {
    /** The app language, then English, then Greek (contract fallback order). */
    fun text(lang: AppLanguage): String {
        val own = when (lang) {
            AppLanguage.GREEK -> el
            AppLanguage.ALBANIAN -> sq
            AppLanguage.ITALIAN -> it
            AppLanguage.ENGLISH -> en
        }
        return listOf(own, en, el, sq, it).firstOrNull { !it.isNullOrBlank() }.orEmpty()
    }

    val isBlank: Boolean get() = listOf(en, el, sq, it).all { it.isNullOrBlank() }
}

enum class ClosureMode(val raw: String) {
    CLOSED("closed"),
    PASS_THROUGH("pass_through"),
    EXIT_ONLY("exit_only"),
    ENTRY_ONLY("entry_only");

    companion object {
        /** Unknown modes return null so a newer server value is ignored, not guessed. */
        fun fromRaw(raw: String?): ClosureMode? = entries.firstOrNull { it.raw == raw }
    }
}

data class ReplacementBusStop(val name: LocalizedText, val lat: Double?, val lon: Double?)

data class ReplacementBus(
    val label: LocalizedText,
    val fromStop: LocalizedText?,
    val toStop: LocalizedText?,
    val headwayMinutes: Int?,
    val stops: List<ReplacementBusStop> = emptyList(),
)

data class StationClosure(
    val id: String,
    val stationIds: List<String>,
    val lineIds: List<String> = emptyList(),
    val mode: ClosureMode,
    val startsAtEpochSeconds: Long,
    val endsAtEpochSeconds: Long?,
    val status: String = "scheduled",
    val reason: LocalizedText? = null,
    val replacementBus: ReplacementBus? = null,
    val source: String = "admin",
)

/** The effect of every closure on one (station, line) at one instant. */
data class ClosureEffect(
    val active: Boolean,
    val mode: ClosureMode?,
    val canBoard: Boolean,
    val canAlight: Boolean,
    val closureId: String?,
    val endsAtEpochSeconds: Long?,
    val upcomingClosureId: String?,
    val upcomingStartsAtEpochSeconds: Long?,
) {
    companion object {
        val NONE = ClosureEffect(
            active = false, mode = null, canBoard = true, canAlight = true,
            closureId = null, endsAtEpochSeconds = null,
            upcomingClosureId = null, upcomingStartsAtEpochSeconds = null,
        )
    }
}

object StationClosures {
    private val MODE_ORDER = listOf(
        ClosureMode.CLOSED, ClosureMode.PASS_THROUGH, ClosureMode.EXIT_ONLY, ClosureMode.ENTRY_ONLY,
    )
    const val UPCOMING_WINDOW_SECONDS: Long = 24 * 3600

    private fun isIgnored(c: StationClosure) = c.status == "draft" || c.status == "cancelled"

    fun isActive(c: StationClosure, now: Long): Boolean {
        if (isIgnored(c)) return false
        if (now < c.startsAtEpochSeconds) return false
        val ends = c.endsAtEpochSeconds
        return ends == null || now < ends
    }

    fun applies(c: StationClosure, stationId: String, lineId: String?): Boolean {
        if (stationId !in c.stationIds) return false
        return c.lineIds.isEmpty() || lineId == null || lineId in c.lineIds
    }

    fun effect(closures: List<StationClosure>, stationId: String, lineId: String?, now: Long): ClosureEffect {
        val active = closures.filter { applies(it, stationId, lineId) && isActive(it, now) }
        if (active.isEmpty()) {
            val upcoming = closures
                .filter {
                    applies(it, stationId, lineId) && !isIgnored(it) &&
                        now < it.startsAtEpochSeconds && it.startsAtEpochSeconds <= now + UPCOMING_WINDOW_SECONDS
                }
                .sortedWith(compareBy<StationClosure> { it.startsAtEpochSeconds }.thenBy { it.id })
                .firstOrNull()
            return ClosureEffect.NONE.copy(
                upcomingClosureId = upcoming?.id,
                upcomingStartsAtEpochSeconds = upcoming?.startsAtEpochSeconds,
            )
        }
        val canBoard = active.all { it.mode == ClosureMode.ENTRY_ONLY }
        val canAlight = active.all { it.mode == ClosureMode.EXIT_ONLY }
        val mode = if (!canBoard && !canAlight) {
            val modes = active.map { it.mode }.toSet()
            val m = MODE_ORDER.first { it in modes }
            // exit_only + entry_only together leave nothing open.
            if (m == ClosureMode.EXIT_ONLY || m == ClosureMode.ENTRY_ONLY) ClosureMode.CLOSED else m
        } else {
            active.first().mode
        }
        val primary = active.sortedWith(
            compareBy<StationClosure> { MODE_ORDER.indexOf(it.mode) }.thenBy { it.id },
        ).first()
        // Latest end wins; any open-ended closure means "until further notice".
        val ends = active.map { it.endsAtEpochSeconds }
        val endsAt = if (ends.any { it == null }) null else ends.maxOf { it!! }
        return ClosureEffect(
            active = true, mode = mode, canBoard = canBoard, canAlight = canAlight,
            closureId = primary.id, endsAtEpochSeconds = endsAt,
            upcomingClosureId = null, upcomingStartsAtEpochSeconds = null,
        )
    }

    /** The closure record behind an effect (active primary or the upcoming one). */
    fun closureFor(closures: List<StationClosure>, effect: ClosureEffect): StationClosure? {
        val id = effect.closureId ?: effect.upcomingClosureId ?: return null
        return closures.firstOrNull { it.id == id }
    }

    /**
     * Station ids whose board is empty right now (boarding forbidden on at least
     * one line), for the map grey-out and the Home/favourites badge. A station with
     * a line-scoped closure counts as closed for that station id when the station's
     * own line is listed, or the closure has no line list.
     */
    fun closedStationIds(closures: List<StationClosure>, now: Long): Set<String> =
        closures.asSequence()
            .filter { isActive(it, now) && it.mode != ClosureMode.ENTRY_ONLY }
            .flatMap { it.stationIds.asSequence() }
            .filter { sid -> !effect(closures, sid, lineIdOfStation(sid), now).canBoard }
            .toSet()

    /**
     * Best-effort line id from a per-line station id such as `M3_SYN` -> `M3`.
     * Station ids in this repo are `<LINE>_<CODE>`; anything else yields null,
     * which [applies] treats as "any line".
     */
    fun lineIdOfStation(stationId: String): String? =
        stationId.substringBefore('_', "").takeIf { it.isNotEmpty() }
}
